CREATE TABLE classes(id INTEGER PRIMARY KEY,name TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',written_weight REAL NOT NULL DEFAULT 50 CHECK(written_weight>=0 AND written_weight<=100),oral_weight REAL NOT NULL DEFAULT 50 CHECK(oral_weight>=0 AND oral_weight<=100),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(abs(written_weight+oral_weight-100)<0.001));
CREATE TABLE students(id INTEGER PRIMARY KEY,class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,first_name TEXT NOT NULL,last_name TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assessments(id INTEGER PRIMARY KEY,class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('written','test','oral')),date TEXT NOT NULL,weight REAL NOT NULL CHECK(weight>0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE grades(id INTEGER PRIMARY KEY,assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE,student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,points INTEGER CHECK(points BETWEEN 0 AND 15),status TEXT NOT NULL DEFAULT 'grade' CHECK(status IN ('grade','absent')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(assessment_id,student_id));
CREATE TABLE sessions(token TEXT PRIMARY KEY,data BLOB NOT NULL,expiry REAL NOT NULL);
CREATE INDEX sessions_expiry_idx ON sessions(expiry);
